#!/usr/bin/env python3
import os, base64

DIRS = ['prompts', 'src', 'src/langx', 'src/langx/nodes', 'streamlit', 'streamlit/streamlit_components']

FILES = {
    'README.md': '',
    'prompts/extraction_prompt.md': '',
    'src/chatbot.py': '',
    'src/db_utils.py': '',
    'src/langx/__init__.py': 'IA==',
    'src/langx/instantiate_llm.py': '',
    'src/langx/nodes/__init__.py': 'IiIiCk5vZGVzIHBhY2thZ2UgZm9yIHRoZSBBSSBhZ2VudCB3b3JrZmxvdy4KClRoaXMgcGFja2FnZSBjb250YWlucyBhbGwgdGhlIG5vZGUgZnVuY3Rpb25zIHVzZWQgaW4gdGhlIExhbmdHcmFwaCB3b3JrZmxvdwpmb3IgZGF0YSBhbmFseXNpcyB0YXNrcywgb3JnYW5pemVkIGludG8gc2VwYXJhdGUgbW9kdWxlcy4KIiIiCg==',
    'src/utils.py': '',
    'streamlit/__init__.py': 'IA==',
    'streamlit/main.py': '',
    'streamlit/streamlit_components/__init__.py': '',
    'streamlit/streamlit_components/render_chat.py': '',
    'streamlit/streamlit_components/render_database_management.py': '',
    'streamlit/streamlit_components/render_document_upload.py': '',
    'streamlit/streamlit_components/render_extracted_term_sheets.py': '',
    'streamlit/streamlit_components/render_pdf_viewer.py': '',
    'streamlit/streamlit_components/render_term_sheet_info.py': '',
    'streamlit/streamlit_utils.py': '',
}

def main():
    # Create directories
    for d in DIRS:
        os.makedirs(d, exist_ok=True)

    # Write files
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        full_path = os.path.abspath(path)
        dirpath = os.path.dirname(full_path)
        os.makedirs(dirpath, exist_ok=True)
        with open(full_path, "wb") as f:
            f.write(data)

if __name__ == "__main__":
    main()
